            accel_cmd = self.pid_distance.compute(control_error, dt)

            if distance_error < 0 and accel_cmd > 0:
                self.pid_distance.reset()
                accel_cmd = self.pid_distance.compute(control_error, dt)

            if distance_error < 0:
                accel_cmd = min(accel_cmd, 0.0)
